// Decisões do João (06/10/2026): só campanhas com envio desde 01/10; automação contínua = 1 linha, números acumulados.
// Sem dado pessoal: assunto, nome da lista e totais. Projeto sai da [SIGLA] no nome (casado no banco).
const INICIO = '2026-10-01';
const camps = [], assunto = {}, listas = {};
for (const it of $input.all()) {
  const b = it.json || {};
  for (const c of b.campaigns || []) camps.push(c);
  for (const m of b.campaignMessages || []) { const k = String(m.campaign); if (!(k in assunto)) assunto[k] = m.subject; }
  for (const l of b.campaignLists || []) { const k = String(l.campaign); (listas[k] = listas[k] || []).push(l.name || ('lista ' + l.list)); }
}
const n = (v) => { const x = parseInt(v, 10); return Number.isFinite(x) ? x : 0; };
const visto = new Set(), lote = [];
for (const c of camps) {
  if (visto.has(c.id)) continue; visto.add(c.id);
  if (!['1', '2', '5'].includes(String(c.status)) || !c.sdate) continue;
  if ((c.ldate || '') < INICIO && c.sdate < INICIO) continue;
  const env = n(c.send_amt); if (env <= 0) continue;
  const fal = n(c.hardbounces) + n(c.softbounces);
  lote.push({
    id_externo: String(c.id),
    campanha: c.name,
    enviado_em: c.sdate,
    canal: 'email',
    copy_texto: String(assunto[c.id] || c.name).slice(0, 2000),
    copy_link: `https://drmarciosa79109.activehosted.com/report/#/campaign/${c.id}/overview`,
    publico_lista: ((listas[c.id] || []).join(', ') || 'lista não informada pelo AC').slice(0, 200),
    tamanho_lista: env,
    entregues: Math.max(env - fal, 0),
    lidas: n(c.uniqueopens),
    cliques: n(c.uniquelinkclicks),
    falhas: fal,
  });
}
return [{ json: { total: lote.length, lote: lote.slice(0, 1000) } }];
